def gen(rng):
    def rand_tree(n, lo, hi, deep=0.0):
        vals = [rng.randint(lo, hi) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        slots = [(0, 0), (0, 1)]
        for i in range(1, n):
            if deep and rng.random() < deep:
                idx = len(slots) - 1 - rng.randint(0, min(1, len(slots) - 1))
            else:
                idx = rng.randrange(len(slots))
            slots[idx], slots[-1] = slots[-1], slots[idx]
            p, side = slots.pop()
            (R if side else L)[p] = i
            slots.append((i, 0))
            slots.append((i, 1))
        return vals, L, R

    def ser(t):
        vals, L, R = t
        if not vals:
            return ['null']
        out = [str(vals[0])]
        q = [0]
        qi = 0
        while qi < len(q):
            u = q[qi]
            qi += 1
            for ch in (L[u], R[u]):
                if ch == -1:
                    out.append('null')
                else:
                    out.append(str(vals[ch]))
                    q.append(ch)
        while out[-1] == 'null' and len(out) > 1:
            out.pop()
        return out

    def fmt(a, b):
        return f'{len(a)}\n{" ".join(a)}\n{len(b)}\n{" ".join(b)}'

    def copy(t):
        return list(t[0]), list(t[1]), list(t[2])

    def mutate(t):
        vals, L, R = copy(t)
        n = len(vals)
        kind = rng.randint(0, 3)
        if kind == 0:
            u = rng.randrange(n)
            vals[u] += rng.choice([-1, 1])
        elif kind == 1:
            cands = [u for u in range(n) if L[u] != -1 and L[L[u]] == -1 and R[L[u]] == -1]
            cands += [u for u in range(n) if R[u] != -1 and L[R[u]] == -1 and R[R[u]] == -1]
            if not cands:
                vals[0] += 1
            else:
                u = rng.choice(cands)
                if L[u] != -1 and L[L[u]] == -1 and R[L[u]] == -1:
                    L[u] = -1
                else:
                    R[u] = -1
        elif kind == 2:
            cands = [u for u in range(n) if L[u] != R[u]]
            if not cands:
                vals[0] += 1
            else:
                u = rng.choice(cands)
                L[u], R[u] = R[u], L[u]
        else:
            u = rng.randrange(n)
            if L[u] == -1:
                vals.append(rng.randint(-5, 5)); L.append(-1); R.append(-1)
                L[u] = len(vals) - 1
            elif R[u] == -1:
                vals.append(rng.randint(-5, 5)); L.append(-1); R.append(-1)
                R[u] = len(vals) - 1
            else:
                vals[u] += 1
        return vals, L, R

    tests = [fmt(['null'], ['null']), fmt(['1'], ['1']), fmt(['1'], ['2']), fmt(['null'], ['0']),
             fmt(['1', '2'], ['1', 'null', '2']), fmt(['1', '2', '3'], ['1', '2', '3']),
             fmt(['1', '2', '3'], ['1', '3', '2']), fmt(['1', 'null', '2'], ['1', 'null', '2']),
             fmt(['-5', '0', 'null'], ['-5', '0']), fmt(['1', '2', '1'], ['1', '2', '1', 'null', 'null'])]
    for n in (1, 2, 3, 4, 5, 6, 8):
        for _ in range(3):
            tests.append(fmt(ser(rand_tree(n, 1, 2)), ser(rand_tree(rng.randint(max(1, n - 1), n + 1), 1, 2))))
